function updateRatingButtons(currentRating, newRating) {
    // Convert values to integers and multiply by 100
    const currentRatingValue = Math.round(currentRating * 100);
    const newRatingValue = Math.round(newRating * 100);

    // Create arrays to store rating values
    const currentRatingArray = Array(5).fill(0).map((_, i) => Math.floor(currentRatingValue / 20 * (i + 1)));
    const newRatingArray = Array(5).fill(0).map((_, i) => Math.floor(newRatingValue / 20 * (i + 1)));

    // Create a tuple array to store changes
    const changes = Array(5).fill(0).map((_, i) => [
        currentRatingArray[i],
        newRatingArray[i],
        currentRatingArray[i] !== newRatingArray[i]
    ]);

    // Update rating buttons
    ratingButtons.forEach((btn, index) => {
        const [current, newRating, changed] = changes[index];
        if (changed) {
            btn.classList.remove(...btn.classList);
            btn.classList.add(`rating-${newRating}`);
        }
    });
}
